import sys

def solve():
    import sys
    import collections

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < n

    def dfs(x, y, color):
        stack = [(x, y)]
        visited.add((x, y))
        grid[x][y] = color
        while stack:
            cx, cy = stack.pop()
            count_neighbors = 0
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = cx + dx, cy + dy
                if is_valid(nx, ny):
                    if grid[nx][ny] == color:
                        count_neighbors += 1
                    elif grid[nx][ny] != '.':
                        count_neighbors -= 1
            if count_neighbors != 2:
                return False
            for dx, dy in [(-1, 0), (0, -1)]:
                nx, ny = cx + dx, cy + dy

                if is_valid(nx, ny) and grid[nx][ny] == '.':
                    grid[nx][ny] = 'S' if color == 'G' else 'G'
                    if not dfs(nx, ny, grid[nx][ny]):
                        return False
                    visited.add((nx, ny))
        return True

    input = sys.stdin.read().split()
    n = int(input[0])
    grid = [list(row) for row in input[1:]]

    visited = set()
    start_points = []
    for i in range(n):
        for j in range(n):
            if grid[i][j] != '.' and (i, j) not in visited:
                start_points.append((i, j))

    if not start_points:
        if n == 1:
            print("NONE")
            return
        start_points.append((0, 0))

    possible = []
    for i, j in start_points:
        if grid[i][j] == '.':
            grid_copy = [row[:] for row in grid]
            if dfs(i, j, 'S'):
                possible.append(('S', grid_copy))
            grid = [row[:] for row in grid_copy]
            if dfs(i, j, 'G'):
                possible.append(('G', grid_copy))
        else:
            grid_copy = [row[:] for row in grid]
            if not dfs(i, j, grid[i][j]):
                print("NONE")
                return

    if len(possible) > 1:
        print("MULTIPLE")
    elif len(possible) == 0:
        print("NONE")
    else:
        print("UNIQUE")
        for row in possible[0][1]:
            print(''.join(row))

solve()
